// Enqueue: reserve tail slot atomically
uint64_t tail = atomic_fetch_add(&q->tail, 1);
Slot* slot = &q->slots[tail % N];

// Spin until slot is available
while (atomic_load(&slot->seq) != tail) { cpu_pause(); }

// Write payload to PMEM
memcpy(slot->payload, data, len);

// Persist in order: payload then sequence
atomic_store(&slot->seq, tail + 1);
clflushopt(slot);      // flush cache line to PMEM
sfence();               // ensure durability
```

